	drainQueue()
	writerMu.Lock()
	out, err := exec.Command("../sql/init.sh").CombinedOutput()
	if err != nil {
		writerMu.Unlock()
		log.Printf("init.sh failed: %s", out)
		httpErr(w, 500, "failed to initialize: "+err.Error())
		return
