func writeJSON(w http.ResponseWriter, code int, b []byte) {
	hd := w.Header()
	hd["Content-Type"] = jsonCT
	hd["Content-Length"] = []string{strconv.Itoa(len(b))}
	w.WriteHeader(code)
	w.Write(b)
}

