func httpErr(w http.ResponseWriter, code int, msg string) {
	b := []byte(`{"error":`)
	b = appendStr(b, "code="+strconv.Itoa(code)+", message="+msg)
	b = append(b, '}')
	writeJSON(w, code, b)
