}

func getUserHandler(w http.ResponseWriter, r *http.Request, name string) {
	if _, ok := auth(w, r); !ok {
		return
	}
	mu.RLock()
	u := usersByName[name]
	var b []byte
	if u != nil {
		b = u.json
	}
