func getThemeHandler(w http.ResponseWriter, r *http.Request, name string) {
	if _, ok := auth(w, r); !ok {
		return
	}
	mu.RLock()
	u := usersByName[name]
	var b []byte
	if u != nil {
		b = append(b, `{"id":`...)
		b = appendInt(b, u.ThemeID)
		if u.Dark {
			b = append(b, `,"dark_mode":true}`...)
		} else {
			b = append(b, `,"dark_mode":false}`...)
